/**
 * KS-466 (item 1) — oauth_apps INSERT must satisfy fail-closed RLS.
 *
 * After the KS-458 fail-closed flip (migration 039), the oauth_apps INSERT
 * regressed to a 500 ("new row violates row-level security policy"): it wrote
 * `tenant_id = params.tenantId || null` and called query() without the explicit
 * tenant arg, so a tenantless admin inserted a NULL tenant_id (forbidden under
 * fail-closed) and no matching session GUC was bundled into the transaction.
 *
 * The fix defaults the tenant to the platform default and passes it to query()
 * as the explicit 3rd arg (the GUC-bundling path — same pattern as
 * userRepo.createUser). This test pins both: the inserted tenant_id is never
 * NULL, and it equals the GUC arg.
 */
import { describe, it, expect, vi, beforeEach } from 'vitest';

const DEFAULT_TENANT_ID = 'a0000000-0000-4000-8000-000000000001';

// Capture every query() call; return a usable app row for the post-INSERT
// getAppByClientId SELECT so createApp resolves.
const query = vi.hoisted(() =>
  vi.fn(async (text: string) => {
    if (/^SELECT/i.test(String(text ?? '').trim())) {
      return {
        rows: [
          {
            id: 'app_1',
            name: 'x',
            client_id: 'sec_abc',
            redirect_uris: ['https://example.com/cb'],
            allowed_scopes: ['documents:read'],
            app_type: 'public',
            tenant_id: DEFAULT_TENANT_ID,
            is_active: true,
          },
        ],
      };
    }
    return { rows: [] };
  }),
);
vi.mock('../db', () => ({ query }));
vi.mock('../utils/logger', () => ({ logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() } }));

import { createApp } from '../services/oauth';

/**
 * Return the arguments of the single INSERT INTO oauth_apps query() call.
 *
 * @returns The `[sql, values, tenantId]` tuple passed to the mocked query().
 */
function insertCall(): [string, unknown[], string | undefined] {
  const call = query.mock.calls.find((c) => /INSERT INTO oauth_apps/i.test(String(c[0])));
  if (!call) throw new Error('no oauth_apps INSERT was issued');
  return call as [string, unknown[], string | undefined];
}

// The INSERT column order — tenant_id is the 9th column ($9), organization_id the 8th.
const TENANT_ID_VALUE_INDEX = 8;

describe('KS-466 — createApp satisfies fail-closed RLS', () => {
  beforeEach(() => query.mockClear());

  it('defaults a tenantless caller to the platform tenant (never NULL) and bundles the matching GUC', async () => {
    await createApp({ name: 'a', redirectUris: ['https://example.com/cb'] });
    const [, values, gucTenantId] = insertCall();
    // Row value is never NULL and equals the GUC passed to query() (the WITH
    // CHECK requires row tenant_id === session GUC).
    expect(values[TENANT_ID_VALUE_INDEX]).toBe(DEFAULT_TENANT_ID);
    expect(gucTenantId).toBe(DEFAULT_TENANT_ID);
  });

  it("uses the caller's own tenant when supplied, for both the row and the GUC", async () => {
    const tenant = 'b3000000-0000-4000-8000-000000000001';
    await createApp({ name: 'a', redirectUris: ['https://example.com/cb'], tenantId: tenant });
    const [, values, gucTenantId] = insertCall();
    expect(values[TENANT_ID_VALUE_INDEX]).toBe(tenant);
    expect(gucTenantId).toBe(tenant);
  });
});

/**
 * KS-839: an OAuth app whose allowedScopes holds the wildcard is granted
 * nothing, instead of everything it asks for.
 *
 * validateScopes returned the request unfiltered when the allow-list held the
 * wildcard, so an unknown scope, or the wildcard itself, was granted and stored
 * on the authorization code. The authorize resolver passes the allow-list as
 * the request when scope is omitted, so that path granted the wildcard too.
 *
 * Round 2: an allow-list ENTRY that only tokenizes to the wildcard (' *', 'openid,*')
 * passed the exact-string test. With scope omitted the resolver grants the allow-list,
 * joins it onto the code with ' ', and the token route re-splits it with
 * parseScopeString, so the token held '*'. validateScopes now splits every entry with
 * that same function before testing for the wildcard.
 */
import { describe, it, expect, vi } from 'vitest';

vi.mock('../db', () => ({
  query: vi.fn(async () => ({ rows: [], rowCount: 0 })),
}));

vi.mock('../utils/logger', () => ({
  logger: { info: vi.fn(), warn: vi.fn(), error: vi.fn(), debug: vi.fn() },
}));

import { validateScopes, parseScopeString } from '../services/oauth';

const EXPECTED_CELLS = 6;
let CELLS_RUN = 0;
const WILDCARD_APP = ['*'];
const MIXED_APP = ['documents:read', '*'];
const NAMED_APP = ['documents:read', 'openid'];

// Allow-lists whose entries tokenize to the wildcard. The drafter measured all eight
// minting '*' end to end with scope omitted (registration stores each verbatim).
const PADDED_CARRIERS: Array<[string, string[]]> = [
  ['space-star', [' *']],
  ['star-space', ['* ']],
  ['tab-star', ['\t*']],
  ['star-newline', ['*\n']],
  ['comma-star', [',*']],
  ['openid-space-star', ['openid *']],
  ['openid-comma-star', ['openid,*']],
  ['openid-then-space-star', ['openid', ' *']],
];

// What a code minted with scope OMITTED carries into the token: the resolver grants
// validateScopes(allowList, allowList), the code stores it joined with ' ', and the token
// route parses that string back with parseScopeString (routes/oauth.ts).
const mintedWithScopeOmitted = (allowList: string[]) =>
  parseScopeString(validateScopes(allowList, allowList).join(' '));

describe('KS-839 - an allow-list holding the wildcard grants nothing', () => {
  it('KS-839 R1 - a wildcard app asking for a scope nobody registered is granted nothing', () => {
    CELLS_RUN += 1;
    expect(validateScopes(['admin:everything'], WILDCARD_APP)).toEqual([]);
  });
  it('KS-839 R2 - the wildcard itself is never granted, asked for, defaulted or mixed in', () => {
    CELLS_RUN += 1;
    expect([
      validateScopes(['*'], WILDCARD_APP),
      validateScopes(WILDCARD_APP, WILDCARD_APP),
      validateScopes(['documents:read', '*'], MIXED_APP),
    ]).toEqual([[], [], []]);
  });
  it('KS-839 CONTROL - an allow-list without the wildcard still filters to what it names', () => {
    CELLS_RUN += 1;
    expect([
      validateScopes(['documents:read', 'admin:everything', '*'], NAMED_APP),
      validateScopes(['openid'], NAMED_APP),
      validateScopes([], NAMED_APP),
    ]).toEqual([['documents:read'], ['openid'], []]);
  });
  it('KS-839 R3 - a padded wildcard entry grants nothing when scope is omitted, and mints no wildcard', () => {
    CELLS_RUN += 1;
    expect(PADDED_CARRIERS.map(([name, allowList]) => [name, validateScopes(allowList, allowList), mintedWithScopeOmitted(allowList)]))
      .toEqual(PADDED_CARRIERS.map(([name]) => [name, [], []]));
  });
  it('KS-839 R4 - a padded wildcard entry grants nothing when scopes are named', () => {
    CELLS_RUN += 1;
    const named = parseScopeString('openid documents:read admin:everything *');
    expect(PADDED_CARRIERS.map(([name, allowList]) => [name, validateScopes(named, allowList)]))
      .toEqual(PADDED_CARRIERS.map(([name]) => [name, []]));
  });
  it('KS-839 CONTROL 2 - look-alike stars stay literal, and explicit, empty and documents:* lists are unchanged', () => {
    CELLS_RUN += 1;
    expect([
      validateScopes(['*\u200b'], ['*\u200b']),
      mintedWithScopeOmitted(['*\u200b']),
      validateScopes(['\uff0a'], ['\uff0a']),
      mintedWithScopeOmitted(['\uff0a']),
      validateScopes(['documents:read'], ['documents:read', 'openid']),
      validateScopes(['openid'], []),
      validateScopes([], []),
      validateScopes(['documents:*'], ['documents:*']),
    ]).toEqual([['*\u200b'], ['*\u200b'], ['\uff0a'], ['\uff0a'], ['documents:read'], [], [], ['documents:*']]);
  });
  it('KS-839 COMPLETENESS - every graded cell above actually ran', () => {
    expect(CELLS_RUN).toBe(EXPECTED_CELLS);
  });
});
